<?php
declare(strict_types=1);namespace App\Controllers;
use App\Core\Database;use App\Core\Request;
final class ApprovalController extends BaseController {
 public function index(Request $r):void{$this->auth();$this->require('approvals.view');$rows=Database::connection()->query("SELECT ai.*,aw.workflow_name FROM approval_instances ai JOIN approval_workflows aw ON aw.id=ai.workflow_id ORDER BY ai.id DESC LIMIT 200")->fetchAll();$this->view('approvals/index',['rows'=>$rows]);}
 public function act(Request $r):void{$this->auth();$this->csrf();$this->require('approvals.act');$id=(int)$r->input('instance_id');$decision=(string)$r->input('decision');if(!in_array($decision,['approved','rejected','returned'],true)){$this->fail('Invalid decision');return;}$pdo=Database::connection();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM approval_instances WHERE id=? FOR UPDATE');$q->execute([$id]);$instance=$q->fetch();if(!$instance||$instance['status']!=='pending')throw new \RuntimeException('Approval is no longer pending');$q=$pdo->prepare('SELECT * FROM approval_steps WHERE workflow_id=? AND step_order=?');$q->execute([$instance['workflow_id'],$instance['current_step_order']]);$step=$q->fetch();if(!$step)throw new \RuntimeException('Approval step not configured');$user=(int)current_user()['id'];$allowed=$step['approver_user_id']?(int)$step['approver_user_id']===$user:false;if($step['approver_role_id']){$s=$pdo->prepare('SELECT 1 FROM user_roles WHERE user_id=? AND role_id=?');$s->execute([$user,$step['approver_role_id']]);$allowed=(bool)$s->fetchColumn();}if(!$allowed&&!can('approvals.override'))throw new \RuntimeException('You are not an assigned approver');$pdo->prepare('INSERT INTO approval_actions(approval_instance_id,approval_step_id,actor_user_id,decision,comments) VALUES(?,?,?,?,?)')->execute([$id,$step['id'],$user,$decision,trim((string)$r->input('comments'))]);if($decision==='rejected'){$pdo->prepare("UPDATE approval_instances SET status='rejected',completed_at=NOW() WHERE id=?")->execute([$id]);}elseif($decision==='returned'){$pdo->prepare("UPDATE approval_instances SET status='cancelled',completed_at=NOW() WHERE id=?")->execute([$id]);}else{$next=$pdo->prepare('SELECT step_order FROM approval_steps WHERE workflow_id=? AND step_order>? ORDER BY step_order LIMIT 1');$next->execute([$instance['workflow_id'],$instance['current_step_order']]);$n=$next->fetchColumn();if($n===false)$pdo->prepare("UPDATE approval_instances SET status='approved',completed_at=NOW() WHERE id=?")->execute([$id]);else $pdo->prepare('UPDATE approval_instances SET current_step_order=? WHERE id=?')->execute([$n,$id]);}$pdo->commit();\audit_log('approval_'.$decision,'approval_instances',$id,$instance,['decision'=>$decision]);flash('success','Approval action recorded.');}catch(\Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());}redirect('/approvals');}
 private function fail(string $m):void{flash('error',$m);redirect('/approvals');}
}
